package com.printflow.files;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.springframework.stereotype.Component;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Component public class PdfInspector {
 private final Semaphore slots=new Semaphore(2);
 public int pages(Path path){if(!slots.tryAcquire())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"PDF inspection busy; retry shortly");Process child=null;try{
  String executable=Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString();List<String> command=new ArrayList<>(List.of(executable,"-Xmx96m","-Djava.awt.headless=true"));boolean boot;try{Class.forName("org.springframework.boot.loader.launch.PropertiesLauncher");boot=true;}catch(ClassNotFoundException absent){boot=false;}
  if(boot)command.add("-Dloader.main=com.printflow.files.PdfInspectorWorker");String classpath=System.getProperty("java.class.path");if(!boot){var paths=new LinkedHashSet<String>();paths.add(classpath);for(ClassLoader loader=getClass().getClassLoader();loader!=null;loader=loader.getParent())if(loader instanceof java.net.URLClassLoader urls)for(var url:urls.getURLs())if(url.getProtocol().equals("file"))paths.add(Path.of(url.toURI()).toString());classpath=String.join(java.io.File.pathSeparator,paths);}command.addAll(List.of("-cp",classpath,boot?"org.springframework.boot.loader.launch.PropertiesLauncher":"com.printflow.files.PdfInspectorWorker",path.toAbsolutePath().toString()));
  child=new ProcessBuilder(command).redirectError(ProcessBuilder.Redirect.DISCARD).start();if(!child.waitFor(10,TimeUnit.SECONDS)){child.destroyForcibly();throw new IllegalArgumentException("PDF inspection timed out");}String value=new String(child.getInputStream().readNBytes(12),java.nio.charset.StandardCharsets.US_ASCII).trim();if(child.exitValue()!=0)throw new IllegalArgumentException("Unsupported PDF");int count=Integer.parseInt(value);if(count<1||count>100)throw new IllegalArgumentException("Unsupported page count");return count;
 }catch(Exception invalid){if(invalid instanceof InterruptedException)Thread.currentThread().interrupt();throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Preview needs an unencrypted, readable PDF with 1–100 pages. Ask the designer to export a new PDF.");}finally{if(child!=null&&child.isAlive())child.destroyForcibly();slots.release();}}
}
